cards.solution:
function ambilMenu() {
  return new Promise((_, rej) => setTimeout(() => rej(new Error("Server mati")), 100));
}
ambilMenu()
  .catch((err) => {
    console.log("Gagal:", err.message);
    return ["kopi", "teh"];
  })
  .then((menu) => console.log("Menu:", menu.join(", ")));
